window.BlackoutMap = (function () {
  const NS = "http://www.w3.org/2000/svg";
  const RADII = [0, 200, 350, 480, 600, 710, 810, 900];
  function reducedMotion() {
    try { return Boolean(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches); } catch (e) { return false; }
  }
  function radiusFor(depth) {
    if (depth < RADII.length) { return RADII[depth]; }
    return RADII[RADII.length - 1] + (depth - RADII.length + 1) * 90;
  }
  function leafCount(node) {
    const children = node.children || [];
    if (!children.length) { return 1; }
    let total = 0;
    children.forEach(function (child) { total += leafCount(child); });
    return Math.max(1, total);
  }
  function charUnits(text) {
    let units = 0;
    String(text).split("").forEach(function (ch) { units += ch.charCodeAt(0) > 255 ? 2 : 1; });
    return units;
  }
  function wrapLabel(text, taskKind, taskStatus) {
    let full = String(text || "");
    if (taskKind === "task") {
      if (taskStatus === "running") { full = (full.indexOf("写") >= 0 ? "在写：" : "在查：") + full; }
    }
    const maxUnits = 24;
    const lines = [];
    let line = "";
    String(full).split("").forEach(function (ch) {
      if (charUnits(line + ch) > maxUnits && line) { lines.push(line); line = ch; } else { line += ch; }
    });
    if (line) { lines.push(line); }
    if (!lines.length) { lines.push(""); }
    if (lines.length > 2) {
      let second = lines[1];
      while (charUnits(second) > maxUnits - 2 && second.length) { second = second.slice(0, -1); }
      return { lines: [lines[0], second + "…"], full: full };
    }
    return { lines: lines, full: full };
  }
  function layout(tree) {
    const nodes = [];
    const byId = {};
    function place(node, depth, start, end, parent) {
      const angle = depth === 0 ? -Math.PI / 2 : (start + end) / 2;
      const radius = radiusFor(depth);
      const item = {
        node: node, depth: depth, angle: angle,
        x: depth === 0 ? 0 : Math.cos(angle) * radius,
        y: depth === 0 ? 0 : Math.sin(angle) * radius,
        parent: parent
      };
      nodes.push(item);
      byId[String(node.id)] = item;
      const children = node.children || [];
      const total = leafCount(node);
      let cursor = start;
      children.forEach(function (child) {
        const span = (end - start) * (leafCount(child) / total);
        place(child, depth + 1, cursor, cursor + span, item);
        cursor += span;
      });
      return item;
    }
    place(tree, 0, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2, null);
    return { nodes: nodes, byId: byId };
  }
  function colors(theme) {
    if (theme === "paper") {
      return { line: "#d9d1c1", text: "#1c1a17", dim: "#6b655a", star: "#1c1a17", amber: "#b07d1e", signal: "#e5604d", parked: "#7d93b2" };
    }
    return { line: "#3a3833", text: "#f4efe6", dim: "#8a8478", star: "#f4efe6", amber: "#e8b44c", signal: "#e5604d", parked: "#7d93b2" };
  }
  function make(tag, attrs) {
    const node = document.createElementNS(NS, tag);
    Object.keys(attrs || {}).forEach(function (key) { node.setAttribute(key, String(attrs[key])); });
    return node;
  }
  function labelWidth(lines, kind) {
    const size = kind === "goal" ? 21 : 15;
    let max = 0;
    lines.forEach(function (line) { max = Math.max(max, charUnits(line) * size * 0.52); });
    return max;
  }
  function bbox(nodes, theme) {
    let minX = -60; let maxX = 60; let minY = -40; let maxY = 40;
    nodes.forEach(function (item) {
      const wrapped = wrapLabel(item.node.text, item.node.kind, item.node.status);
      const w = labelWidth(wrapped.lines, item.node.kind);
      const right = Math.cos(item.angle) >= 0 || item.depth === 0;
      const lx = item.depth === 0 ? item.x - w / 2 : (right ? item.x + 12 : item.x - 12 - w);
      minX = Math.min(minX, lx - 8, item.x - 12);
      maxX = Math.max(maxX, lx + w + 8, item.x + 12);
      minY = Math.min(minY, item.y - 24);
      maxY = Math.max(maxY, item.y + wrapped.lines.length * 18 + 8);
    });
    return { x: minX - 36, y: minY - 36, w: (maxX - minX) + 72, h: (maxY - minY) + 72 };
  }
  function markFor(item, palette, theme) {
    const kind = item.node.kind;
    const g = make("g", {});
    if (kind === "goal") { return g; }
    if (kind === "point" && item.node.status === "未展开") {
      const ring = make("circle", { r: 7, fill: "none", stroke: palette.amber, "stroke-width": 2 });
      ring.setAttribute("class", "map-unexpanded");
      g.appendChild(ring);
    } else if (kind === "point") {
      g.appendChild(make("circle", { r: 5, fill: palette.star, class: theme === "paper" ? "" : "map-glow" }));
    } else if (kind === "decision") {
      g.appendChild(make("path", { d: "M0,-7 L6,0 L0,7 L-6,0 Z", fill: palette.star }));
    } else if (kind === "todo") {
      g.appendChild(make("rect", { x: -5, y: -5, width: 10, height: 10, fill: "none", stroke: palette.text, "stroke-width": 1.6 }));
    } else if (kind === "question") {
      g.appendChild(make("circle", { r: 6, fill: "none", stroke: palette.parked, "stroke-width": 1.8 }));
    } else if (kind === "contradiction") {
      g.appendChild(make("path", { d: "M-6,0 L6,0 M0,-6 L0,6", stroke: palette.signal, "stroke-width": 2.4 }));
    } else if (kind === "task") {
      const fill = item.node.status === "failed" ? palette.dim : (item.node.status === "done" ? palette.star : palette.amber);
      const dot = make("circle", { r: item.node.status === "running" ? 6 : 4.5, fill: fill });
      if (item.node.status === "running" && theme !== "paper") { dot.setAttribute("class", "map-pulse"); }
      g.appendChild(dot);
    } else {
      g.appendChild(make("circle", { r: 4, fill: palette.text }));
    }
    return g;
  }
  function render(svg, tree, options) {
    if (!svg || !tree) { return; }
    const opts = options || {};
    const theme = opts.theme === "paper" ? "paper" : "night";
    const animate = Boolean(opts.animate) && theme !== "paper" && !reducedMotion();
    const signature = JSON.stringify(tree) + "|" + theme;
    if (svg._blackoutSignature === signature) { return; }
    const previous = svg._blackoutPositions || {};
    const seenBefore = svg._blackoutSeen || {};
    const laid = layout(tree);
    const palette = colors(theme);
    const box = bbox(laid.nodes, theme);
    const clientW = svg.clientWidth || 1280;
    if (box.w < clientW / 1.2) { const extra = clientW / 1.2 - box.w; box.x -= extra / 2; box.w += extra; }
    const fromBox = svg._blackoutBox || box;
    function draw(progress, positions, view) {
      while (svg.firstChild) { svg.removeChild(svg.firstChild); }
      svg.setAttribute("viewBox", view.x + " " + view.y + " " + view.w + " " + view.h);
      const style = make("style", {});
      style.textContent = ".map-glow{filter:drop-shadow(0 0 7px rgba(244,239,230,.85))}.map-pulse{animation:mp 1.6s ease-in-out infinite}.map-unexpanded{animation:mp 2.4s ease-in-out infinite}@keyframes mp{0%,100%{opacity:1}50%{opacity:.35}}@media (prefers-reduced-motion: reduce){.map-pulse,.map-unexpanded{animation:none}}";
      if (theme !== "paper") { svg.appendChild(style); }
      laid.nodes.forEach(function (item) {
        if (!item.parent) { return; }
        const a = positions[String(item.parent.node.id)] || item.parent;
        const b = positions[String(item.node.id)] || item;
        const contra = item.node.kind === "contradiction";
        const line = make("line", {
          x1: a.x, y1: a.y, x2: b.x, y2: b.y,
          stroke: contra ? palette.signal : palette.line,
          "stroke-width": contra ? 1.4 : 1,
          "stroke-dasharray": contra ? "4 4" : "none"
        });
        if (animate && !seenBefore[String(item.node.id)]) {
          const len = Math.max(1, Math.hypot(b.x - a.x, b.y - a.y));
          line.setAttribute("stroke-dasharray", String(len));
          line.setAttribute("stroke-dashoffset", String(len * (1 - progress)));
        }
        svg.appendChild(line);
      });
      laid.nodes.forEach(function (item) {
        const pos = positions[String(item.node.id)] || item;
        const isNew = !seenBefore[String(item.node.id)];
        const g = make("g", { transform: "translate(" + pos.x + "," + pos.y + ")", opacity: animate && isNew ? String(progress) : "1" });
        g.appendChild(markFor(item, palette, theme));
        const wrapped = wrapLabel(item.node.text, item.node.kind, item.node.status);
        const title = make("title", {});
        title.textContent = wrapped.full;
        g.appendChild(title);
        const right = item.depth === 0 || Math.cos(item.angle) >= 0;
        const text = make("text", {
          x: item.depth === 0 ? 0 : (right ? 13 : -13), y: item.depth === 0 ? 7 : 5,
          "text-anchor": item.depth === 0 ? "middle" : (right ? "start" : "end"),
          fill: item.node.kind === "question" ? palette.parked : (item.node.kind === "contradiction" ? palette.signal : palette.text),
          "font-size": item.node.kind === "goal" ? 21 : 15,
          "font-weight": item.node.kind === "goal" ? 300 : (item.node.kind === "decision" ? 600 : 300),
          class: theme !== "paper" && item.node.kind === "goal" ? "map-glow" : ""
        });
        wrapped.lines.forEach(function (lineText, index) {
          const tspan = make("tspan", { x: text.getAttribute("x"), dy: index === 0 ? 0 : 19 });
          tspan.textContent = lineText;
          text.appendChild(tspan);
        });
        g.appendChild(text);
        svg.appendChild(g);
      });
    }
    const finalPositions = {};
    laid.nodes.forEach(function (item) { finalPositions[String(item.node.id)] = { x: item.x, y: item.y }; });
    const startPositions = {};
    laid.nodes.forEach(function (item) {
      const old = previous[String(item.node.id)];
      startPositions[String(item.node.id)] = old ? { x: old.x, y: old.y } : (item.parent && previous[String(item.parent.node.id)] ? { x: previous[String(item.parent.node.id)].x, y: previous[String(item.parent.node.id)].y } : { x: item.x, y: item.y });
    });
    function finish() {
      draw(1, finalPositions, box);
      svg._blackoutSignature = signature;
      svg._blackoutPositions = finalPositions;
      svg._blackoutBox = box;
      const seen = {};
      laid.nodes.forEach(function (item) { seen[String(item.node.id)] = true; });
      svg._blackoutSeen = seen;
    }
    const hasOld = Object.keys(previous).length > 0;
    if (!animate || !hasOld) {
      // First paint appears; brand-new nodes on later paints animate via hasOld path.
      if (animate && !hasOld) { draw(1, finalPositions, box); svg._blackoutSignature = signature; svg._blackoutPositions = finalPositions; svg._blackoutBox = box; const seen = {}; laid.nodes.forEach(function (item) { seen[String(item.node.id)] = true; }); svg._blackoutSeen = seen; return; }
      finish();
      return;
    }
    const started = performance.now();
    function frame(now) {
      const raw = Math.min(1, (now - started) / 600);
      const eased = raw;
      const positions = {};
      laid.nodes.forEach(function (item) {
        const key = String(item.node.id);
        positions[key] = { x: startPositions[key].x + (finalPositions[key].x - startPositions[key].x) * eased, y: startPositions[key].y + (finalPositions[key].y - startPositions[key].y) * eased };
      });
      const view = { x: fromBox.x + (box.x - fromBox.x) * eased, y: fromBox.y + (box.y - fromBox.y) * eased, w: fromBox.w + (box.w - fromBox.w) * eased, h: fromBox.h + (box.h - fromBox.h) * eased };
      draw(eased, positions, view);
      if (raw < 1) { requestAnimationFrame(frame); } else { finish(); }
    }
    requestAnimationFrame(frame);
  }
  return { render: render };
})();
", "path": "app/static/js/map.js"}, {"content": ""use strict";
window.BlackoutObserver = (function () {
  const MIC_LABELS = {
    listening: "在听",
    paused: "暂停",
    user_speaking: "你在说",
    ai_speaking: "AI 在说",
    offline: "未连接"
  };
  const ACTION_LABELS = {
    listen: "听着，没打断",
    follow_up: "追问没说完的点",
    pull_back: "拉回主线",
    continue: "推进",
    answer: "回答",
    summarize: "确认结束"
  };
  let sessionId = "";
  let timer = 0;
  let subtitleTimer = 0;
  let lastParkingJson = "";
  let parkingSeen = false;
  let lastSubtitleText = "";
  function el(id) { return document.getElementById(id); }
  function sessionParam() {
    try { return new URLSearchParams(window.location.search).get("session") || ""; } catch (e) { return ""; }
  }
  function showMessage(text) {
    const node = el("obsMessage");
    node.textContent = String(text || "");
    node.hidden = !text;
  }
  function armSubtitleFade(text) {
    if (text === lastSubtitleText) { return; }
    lastSubtitleText = text;
    const box = document.querySelector(".subtitles");
    if (box) { box.classList.remove("faded"); }
    window.clearTimeout(subtitleTimer);
    subtitleTimer = window.setTimeout(function () {
      if (box) { box.classList.add("faded"); }
    }, 8000);
  }
  function renderParking(parking) {
    const list = el("obsParking");
    const json = JSON.stringify(parking || []);
    const isNew = parkingSeen && json !== lastParkingJson;
    list.replaceChildren();
    (parking || []).forEach(function (item, index) {
      const li = document.createElement("li");
      li.textContent = String(item || "");
      if (isNew && index === (parking || []).length - 1) { li.className = "new"; }
      list.appendChild(li);
    });
    parkingSeen = true;
    lastParkingJson = json;
  }
  function renderSession(record, live) {
    const state = (record && record.state) || {};
    if (window.BlackoutMap && record.map) {
      window.BlackoutMap.render(el("obsMap"), record.map, { theme: "night", animate: true });
    }
    const micKey = Object.prototype.hasOwnProperty.call(MIC_LABELS, live.mic) ? live.mic : "offline";
    const micNode = el("obsMic");
    micNode.textContent = MIC_LABELS[micKey];
    micNode.className = "corner corner-right" + (micKey === "ai_speaking" ? " mic-ai" : "");
    const caption = String(live.partial || live.last_user || "");
    el("obsCaption").textContent = caption;
    const reply = String(live.last_reply || "");
    el("obsReply").textContent = reply;
    const action = String(live.last_action || "");
    const reason = String(live.last_reason || "");
    let decision = "";
    if (action === "listen") { decision = "听着，没打断"; }
    else if (action) { decision = (ACTION_LABELS[action] || action) + (reason ? " · " + reason : ""); }
    el("obsDecision").textContent = reply ? decision : (action === "listen" ? "听着，没打断" : decision);
    armSubtitleFade(caption + "|" + reply + "|" + decision);
    renderParking(state.parking_lot || []);
    const stats = record.stats || {};
    el("obsCounters").textContent = "说了 " + String(stats.user_turns || 0) + " 句 · 开口 " + String(stats.ai_spoke || 0) + " 次 · 拉回 " + String(stats.pull_backs || 0) + " 次";
  }
  function stopPolling() { window.clearInterval(timer); timer = 0; }
  async function fetchJson(url) {
    const response = await fetch(url);
    const data = await response.json();
    if (!response.ok) {
      const message = (data && data.error && data.error.message) || "加载失败。";
      throw new Error(String(message));
    }
    return data;
  }
  async function pollOnce() {
    if (!sessionId) { return; }
    let record = null;
    try { record = await fetchJson("/api/sessions/" + sessionId); }
    catch (e) { showMessage("还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。"); stopPolling(); return; }
    let live = {};
    try { live = await fetchJson("/api/sessions/" + sessionId + "/live"); } catch (e) {}
    renderSession(record, live || {});
    if (record.status === "finished") {
      const title = (record.result && record.result.title) || "成果";
      const banner = el("obsFinished");
      banner.textContent = "灯亮了 · " + String(title);
      banner.hidden = false;
      el("obsMic").textContent = "未连接";
      stopPolling();
    }
  }
  function init() {
    sessionId = sessionParam();
    if (!/^[0-9a-f]{32}$/.test(sessionId)) {
      showMessage("还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。");
      return;
    }
    pollOnce();
    timer = window.setInterval(pollOnce, 1000);
  }
  document.addEventListener("DOMContentLoaded", init);
  return { init: init, pollOnce: pollOnce };
})();
