window.BlackoutResult = (function () {
  let sessionId = "";
  let markdown = "";
  let pollTimer = 0;
  let pollDeadline = 0;
  let lastResultJson = "";
  const STORAGE_KEY = "blackout_active_session_id";
  function el(id) { return document.getElementById(id); }
  function showPage(page) {
    if (page !== "result") { stopTaskPolling(); }
    el("page-start").hidden = page !== "start";
    el("page-black").hidden = page !== "black";
    el("page-result").hidden = page !== "result";
  }
  function stopTaskPolling() {
    window.clearInterval(pollTimer);
    pollTimer = 0;
    pollDeadline = 0;
    lastResultJson = "";
  }
  function hasRunningTask(result) {
    const tasks = (result && result.tasks) || [];
    return tasks.some(function (task) { return Boolean(task && task.status === "running"); });
  }
  async function pollTasksOnce() {
    if (!sessionId || !pollDeadline) { return; }
    if (Date.now() > pollDeadline || el("page-result").hidden) { stopTaskPolling(); return; }
    let record = null;
    try {
      const response = await fetch("/api/sessions/" + sessionId);
      if (!response.ok) { return; }
      record = await response.json();
    } catch (e) { return; }
    if (!record || !record.result) { return; }
    const json = JSON.stringify(record.result);
    if (json !== lastResultJson) { showResult(record.result, sessionId); }
    if (!hasRunningTask(record.result)) { stopTaskPolling(); }
  }
  function startTaskPolling(result) {
    if (!hasRunningTask(result)) { stopTaskPolling(); return; }
    if (!pollDeadline) { pollDeadline = Date.now() + 3 * 60 * 1000; }
    if (!pollTimer) { pollTimer = window.setInterval(pollTasksOnce, 3000); }
  }
  function makeSection(title, items) {
    const box = document.createElement("div");
    box.className = "sec";
    const head = document.createElement("h3");
    head.textContent = title;
    box.appendChild(head);
    const list = document.createElement("ul");
    (items || []).forEach(function (item) {
      const li = document.createElement("li");
      li.textContent = String(item);
      list.appendChild(li);
    });
    box.appendChild(list);
    return box;
  }
  function isWebUrl(value) {
    try {
      const parsed = new URL(String(value));
      return parsed.protocol === "http:" || parsed.protocol === "https:";
    } catch (e) { return false; }
  }
  function makeTasks(tasks) {
    const box = document.createElement("div");
    box.className = "sec";
    const head = document.createElement("h3");
    head.textContent = "后台查到和写好的";
    box.appendChild(head);
    const list = document.createElement("ul");
    (tasks || []).forEach(function (task) {
      const li = document.createElement("li");
      const main = document.createElement("span");
      if (task.status === "running") {
        const verb = task.kind === "draft" ? "还在写……" : "还在查……";
        const detailText = String(task.instruction || "");
        main.textContent = detailText ? verb + detailText : verb;
      } else {
        main.textContent = String(task.conclusion || task.instruction || "");
      }
      li.appendChild(main);
      const sources = (task.sources || []).filter(function (source) { return Boolean(source && isWebUrl(source.url)); });
      if (task.detail || sources.length > 0) {
        const details = document.createElement("details");
        const summary = document.createElement("summary");
        summary.textContent = "详情";
        details.appendChild(summary);
        if (task.detail) {
          const body = document.createElement("p");
          body.textContent = String(task.detail);
          details.appendChild(body);
        }
        sources.forEach(function (source) {
          const link = document.createElement("a");
          link.href = String(source.url);
          link.rel = "noopener noreferrer";
          link.textContent = String(source.title || source.url);
          const line = document.createElement("p");
          line.appendChild(link);
          details.appendChild(line);
        });
        li.appendChild(details);
      }
      list.appendChild(li);
    });
    box.appendChild(list);
    return box;
  }
  function showResult(result, id, options) {
    if (id) {
      const changedSession = sessionId !== String(id);
      sessionId = String(id);
      if (changedSession) { stopTaskPolling(); }
    }
    const data = result || {};
    const lightsOn = Boolean(options && (options.lightsOn || options === true));
    markdown = String(data.markdown || "");
    lastResultJson = JSON.stringify(data);
    el("resultTitle").textContent = String(data.title || "成果");
    const goalNode = el("resultGoal");
    if (goalNode) {
      goalNode.textContent = data.goal && data.goal !== data.title ? String(data.goal) : "";
      goalNode.hidden = !goalNode.textContent;
    }
    el("degradedNotice").hidden = !data.degraded;
    el("resultErr").textContent = "";
    const box = el("result");
    box.replaceChildren();
    let hasContent = false;
    if (data.map && (data.map.children || []).length > 0 && window.BlackoutMap) {
      hasContent = true;
      const hero = document.createElement("div");
      hero.className = "map-hero";
      const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      hero.appendChild(svg);
      box.appendChild(hero);
      window.BlackoutMap.render(svg, data.map, { theme: "paper", animate: false });
    }
    const pairTitles = [];
    if ((data.decisions || []).length > 0) { pairTitles.push(["决定", data.decisions]); }
    if ((data.todos || []).length > 0) { pairTitles.push(["待办", data.todos]); }
    if (pairTitles.length > 0) {
      hasContent = true;
      if (pairTitles.length === 2) {
        const columns = document.createElement("div");
        columns.className = "result-columns";
        pairTitles.forEach(function (pair) { columns.appendChild(makeSection(pair[0], pair[1])); });
        box.appendChild(columns);
      } else {
        box.appendChild(makeSection(pairTitles[0][0], pairTitles[0][1]));
      }
    }
    const sections = [
      ["还没想清楚", data.open_questions], ["前后矛盾", data.contradictions],
      ["没说完的点", data.unexpanded_points], ["停车场", data.parking_lot]
    ];
    sections.forEach(function (pair) {
      if ((pair[1] || []).length > 0) { hasContent = true; box.appendChild(makeSection(pair[0], pair[1])); }
    });
    if ((data.tasks || []).length > 0) { hasContent = true; box.appendChild(makeTasks(data.tasks)); }
    const sketchTexts = (data.sketches || []).map(function (sketch) { return String((sketch && sketch.description) || ""); }).filter(function (text) { return text.length > 0; });
    if (sketchTexts.length > 0) { hasContent = true; box.appendChild(makeSection("纸上草稿", sketchTexts)); }
    if (!hasContent) {
      const empty = document.createElement("p");
      empty.className = "empty-line";
      empty.textContent = "这次没有记下内容。";
      box.appendChild(empty);
    }
    const page = el("page-result");
    page.classList.toggle("light-fade", lightsOn);
    el("page-start").hidden = true;
    el("page-black").hidden = true;
    page.hidden = false;
    startTaskPolling(data);
  }
  function fallbackCopy(text) {
    return new Promise(function (resolve) {
      const area = document.createElement("textarea");
      area.value = text;
      document.body.appendChild(area);
      area.select();
      try { document.execCommand("copy"); } catch (e) {}
      area.remove();
      resolve();
    });
  }
  async function copyMarkdown() {
    const button = el("copyBtn");
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) { await navigator.clipboard.writeText(markdown); }
      else { await fallbackCopy(markdown); }
    } catch (e) { await fallbackCopy(markdown); }
    button.textContent = "已复制";
    window.setTimeout(function () { button.textContent = "复制为 Markdown"; }, 1500);
  }
  function scaleImage(file) {
    return new Promise(function (resolve, reject) {
      const url = URL.createObjectURL(file);
      const image = new Image();
      image.onload = function () {
        try {
          const longSide = Math.max(image.naturalWidth, image.naturalHeight) || 1;
          const ratio = Math.min(1, 1600 / longSide);
          const canvas = document.createElement("canvas");
          canvas.width = Math.max(1, Math.round(image.naturalWidth * ratio));
          canvas.height = Math.max(1, Math.round(image.naturalHeight * ratio));
          const ctx = canvas.getContext("2d");
          ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
          URL.revokeObjectURL(url);
          canvas.toBlob(function (blob) { if (blob) { resolve(blob); } else { reject(new Error("图片处理失败")); } }, "image/jpeg", 0.85);
        } catch (e) { URL.revokeObjectURL(url); reject(e); }
      };
      image.onerror = function () { URL.revokeObjectURL(url); reject(new Error("图片读取失败")); };
      image.src = url;
    });
  }
  async function uploadSketch(file) {
    const label = el("sketchLabel");
    const input = el("sketchInput");
    el("resultErr").textContent = "";
    label.textContent = "正在识别…";
    try {
      const blob = await scaleImage(file);
      const form = new FormData();
      form.append("image", blob, "sketch.jpg");
      const response = await fetch("/api/sessions/" + sessionId + "/sketches", { method: "POST", body: form });
      const data = await response.json();
      if (!response.ok) { throw new Error((data.error && data.error.message) || "草稿识别失败，请再试一次。"); }
      showResult(data, sessionId);
    } catch (e) {
      el("resultErr").textContent = String((e && e.message) || "草稿识别失败，请再试一次。");
    } finally {
      label.textContent = "加入纸上草稿";
      input.value = "";
    }
  }
  function backToStart() {
    stopTaskPolling();
    try { window.localStorage.removeItem(STORAGE_KEY); } catch (e) {}
    showPage("start");
    document.dispatchEvent(new CustomEvent("blackout:restart"));
  }
  function init() {
    el("copyBtn").addEventListener("click", copyMarkdown);
    el("restartBtn").addEventListener("click", backToStart);
    el("sketchInput").addEventListener("change", function () {
      const input = el("sketchInput");
      if (input.files && input.files[0]) { uploadSketch(input.files[0]); }
    });
  }
  document.addEventListener("DOMContentLoaded", init);
  return {
    showResult: showResult,
    showPage: showPage,
    backToStart: backToStart,
    stopTaskPolling: stopTaskPolling,
    setSession: function (id) { sessionId = String(id || ""); }
  };
})();
", "path": "app/static/js/result.js"}, {"content": ""use strict";
window.BlackoutStart = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  let goalRecorder = null;
  let goalRecording = false;
  let goalStarting = false;
  let starting = false;
  let startGeneration = 0;
  function el(id) { return document.getElementById(id); }
  function errorMessage(data) {
    if (data && data.error && data.error.message) { return String(data.error.message); }
    return "出了一点问题，请再试一次。";
  }
  function primeAudio() {
    window.BlackoutCues.ensure();
    if (window.BlackoutCapture && window.BlackoutCapture.prime) { window.BlackoutCapture.prime(); }
    window.BlackoutSpeech.prime();
  }
  function setStartButtonsDisabled(disabled) {
    ["startBtn", "continueLastBtn", "micBtn"].forEach(function (id) {
      const node = el(id);
      if (node) { node.disabled = disabled; }
    });
  }
  async function ensureMic(generation) {
    try { await window.BlackoutCapture.ensurePermission(); }
    catch (e) {
      if (generation !== startGeneration) { return false; }
      if (e && e.name === "NotFoundError") { el("startErr").textContent = "没有找到麦克风。"; }
      else { el("startErr").textContent = "需要麦克风权限才能开始。请在地址栏允许麦克风后重试。"; }
      return false;
    }
    return generation === startGeneration;
  }
  function storedId() {
    try { return window.localStorage.getItem(STORAGE_KEY) || ""; } catch (e) { return ""; }
  }
  function clearStored() {
    try { window.localStorage.removeItem(STORAGE_KEY); } catch (e) {}
  }
  async function fetchJson(url, options) {
    const response = await fetch(url, options || {});
    const data = await response.json();
    if (!response.ok) { throw new Error(errorMessage(data)); }
    return data;
  }
  async function openFinished(id) {
    const record = await fetchJson("/api/sessions/" + id);
    if (record.result) {
      clearStored();
      window.BlackoutResult.showResult(record.result, id);
    }
  }
  async function enterActive(id, resumed) {
    if (starting) { return; }
    starting = true;
    const generation = ++startGeneration;
    primeAudio();
    setStartButtonsDisabled(true);
    try {
      if (!await ensureMic(generation)) { return; }
      if (generation !== startGeneration) { return; }
      try { window.localStorage.setItem(STORAGE_KEY, id); } catch (e) {}
      window.BlackoutBlack.enter(id, resumed);
    } finally {
      starting = false;
      setStartButtonsDisabled(false);
    }
  }
  function makeSessionButton(text, handler) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = text;
    button.addEventListener("click", handler);
    return button;
  }
  function formatDate(value) {
    try {
      const date = new Date(String(value || ""));
      if (isNaN(date.getTime())) { return ""; }
      return date.toLocaleDateString("zh-CN") + " " + date.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" });
    } catch (e) { return ""; }
  }
  async function refreshList() {
    const box = el("recentList");
    box.replaceChildren();
    el("continueLastBtn").hidden = !storedId();
    try {
      const data = await fetchJson("/api/sessions");
      const sessions = data.sessions || [];
      const section = el("recentSection");
      if (section) { section.hidden = sessions.length === 0; }
      sessions.forEach(function (session) {
        const item = document.createElement("div");
        item.className = "session-item";
        const goal = document.createElement("span");
        goal.className = "session-goal";
        goal.textContent = String(session.goal || "");
        item.appendChild(goal);
        const date = document.createElement("span");
        date.className = "session-date";
        date.textContent = formatDate(session.updated_at || session.created_at);
        item.appendChild(date);
        if (session.status === "finished") {
          item.appendChild(makeSessionButton("查看", function () { primeAudio(); openFinished(String(session.id)); }));
        } else {
          item.appendChild(makeSessionButton("继续", function () { primeAudio(); enterActive(String(session.id), true); }));
        }
        item.appendChild(makeSessionButton("删除", async function () {
          if (!window.confirm("确定删除这次思考吗？")) { return; }
          await fetch("/api/sessions/" + session.id, { method: "DELETE" });
          if (storedId() === String(session.id)) { clearStored(); }
          refreshList();
        }));
        box.appendChild(item);
      });
    } catch (e) {}
  }
  function setMicRecording(on) {
    const btn = el("micBtn");
    btn.classList.toggle("recording", Boolean(on));
    btn.setAttribute("aria-label", on ? "停止录音" : "语音输入目标");
  }
  async function stopGoalRecorder(send) {
    if (!goalRecording || !goalRecorder) { return; }
    goalRecording = false;
    const recorder = goalRecorder;
    goalRecorder = null;
    setMicRecording(false);
    if (!send) { await recorder.cancel(); return; }
    const wav = await recorder.stop();
    const form = new FormData();
    form.append("audio", wav, "goal.wav");
    try {
      const data = await fetchJson("/api/transcribe", { method: "POST", body: form });
      el("goalInput").value = String(data.transcript || "");
    } catch (e) {
      el("startErr").textContent = String((e && e.message) || "没听清，请再说一次。");
    }
  }
  async function toggleGoalMic() {
    if (goalStarting || starting) { return; }
    if (goalRecording) { await stopGoalRecorder(true); return; }
    goalStarting = true;
    goalRecorder = window.BlackoutCapture.createWavRecorder();
    try {
      const opened = await goalRecorder.start();
      if (!opened) { goalRecorder = null; goalStarting = false; return; }
      goalRecording = true;
      setMicRecording(true);
      el("startErr").textContent = "正在录目标，再点一次结束。";
    } catch (e) {
      goalRecorder = null;
      setMicRecording(false);
      el("startErr").textContent = "需要麦克风权限，请允许后重试。";
    }
    goalStarting = false;
  }
  async function startNew() {
    if (starting) { return; }
    starting = true;
    const generation = ++startGeneration;
    primeAudio();
    setStartButtonsDisabled(true);
    try {
      const goal = el("goalInput").value.trim();
      el("startErr").textContent = "";
      if (!goal) { el("startErr").textContent = "请先说一下本次目标。"; return; }
      if (!await ensureMic(generation)) { return; }
      if (generation !== startGeneration) { return; }
      const data = await fetchJson("/api/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ goal: goal })
      });
      if (generation !== startGeneration) { return; }
      const id = String(data.session_id);
      try { window.localStorage.setItem(STORAGE_KEY, id); } catch (e) {}
      let skipFullscreen = false;
      if (el("openObserver").checked) {
        skipFullscreen = true;
        window.open("/observer?session=" + encodeURIComponent(id), "_blank");
      }
      window.BlackoutBlack.enter(id, false, { skipFullscreen: skipFullscreen });
    } catch (e) {
      if (generation === startGeneration) { el("startErr").textContent = String((e && e.message) || "网络不太好，请重试。"); }
    } finally {
      starting = false;
      setStartButtonsDisabled(false);
    }
  }
  async function continueLast() {
    if (starting) { return; }
    starting = true;
    const generation = ++startGeneration;
    primeAudio();
    setStartButtonsDisabled(true);
    try {
      const id = storedId();
      if (!id) { return; }
      let record = null;
      try { record = await fetchJson("/api/sessions/" + id); }
      catch (e) { clearStored(); refreshList(); return; }
      if (generation !== startGeneration) { return; }
      if (record.status === "finished" && record.result) {
        clearStored();
        window.BlackoutResult.showResult(record.result, id);
        return;
      }
      if (!await ensureMic(generation)) { return; }
      if (generation !== startGeneration) { return; }
      try { window.localStorage.setItem(STORAGE_KEY, id); } catch (e) {}
      window.BlackoutBlack.enter(id, true);
    } finally {
      starting = false;
      setStartButtonsDisabled(false);
    }
  }
  function backToStart() {
    el("page-black").hidden = true;
    el("page-result").hidden = true;
    el("page-start").hidden = false;
    refreshList();
  }
  async function init() {
    el("startBtn").addEventListener("click", startNew);
    el("continueLastBtn").addEventListener("click", continueLast);
    el("micBtn").addEventListener("click", toggleGoalMic);
    document.addEventListener("blackout:restart", refreshList);
    window.addEventListener("beforeunload", function () {
      if (goalRecorder) { goalRecorder.cancel(); goalRecorder = null; goalRecording = false; }
    });
    refreshList();
    const hasChinese = await window.BlackoutSpeech.hasChineseVoice();
    el("voiceWarning").hidden = hasChinese;
  }
  document.addEventListener("DOMContentLoaded", init);
  return { backToStart: backToStart, refreshList: refreshList };
})();
", "path": "app/static/js/start.js"}, {"content": ""use strict";
window.BlackoutBlack = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  const ENTRY_TEXT = "黑屏开始。我在听，你直接说就行。按空格暂停，想结束就说结束，或者按 Esc。";
  const RESUMED_TEXT = "接着刚才的继续。";
  const FALLBACK_TEXT = "自动听写断了。现在按空格开始说话，说完再按一次。";
  let sessionId = "";
  let socket = null;
  let capture = null;
  let recorder = null;
  let mode = "realtime";
  let paused = false;
  let finishing = false;
  let entered = false;
  let readySeen = false;
  let fallbackSeen = false;
  let intentionalClose = false;
  let wasFullscreen = false;
  let skipFullscreen = false;
  let wakeLock = null;
  let resumedEntry = false;
  let speechEpoch = 0;
  let speechChain = Promise.resolve();
  let ttsPlaying = false;
  let readyTimer = 0;
  let pollTimer = 0;
  let hintTimer = 0;
  let hintRemoveTimer = 0;
  let longPressTimer = 0;
  let suppressTapUntil = 0;
  let pttRecording = false;
  let pttStarting = false;
  let flowGeneration = 0;
  function el(id) { return document.getElementById(id); }
  function showBlack() {
    el("page-start").hidden = true;
    el("page-result").hidden = true;
    el("page-black").hidden = false;
  }
  function showStart() {
    el("page-black").hidden = true;
    el("page-result").hidden = true;
    el("page-start").hidden = false;
    document.dispatchEvent(new CustomEvent("blackout:restart"));
  }
  function setDot(state) { el("dot").className = "dot " + state; }
  function sendJson(payload) {
    try { if (socket && socket.readyState === WebSocket.OPEN) { socket.send(JSON.stringify(payload)); } } catch (e) {}
  }
  function applyMuted() {
    if (capture) { capture.setMuted(paused); }
  }
  function say(text, kind) {
    const epoch = speechEpoch;
    const spoken = String(text || "");
    if (!spoken) { return Promise.resolve(); }
    speechChain = speechChain.then(async function () {
      if (epoch !== speechEpoch || !entered) {
        if (mode === "realtime") { sendJson({ type: "tts_finished" }); }
        return;
      }
      if (kind === "announcement") { window.BlackoutCues.chime(); }
      ttsPlaying = true;
      applyMuted();
      setDot("speaking");
      if (mode === "realtime") { sendJson({ type: "tts_started", text: spoken }); }
      try { await window.BlackoutSpeech.speak(spoken); }
      finally {
        if (mode === "realtime") { sendJson({ type: "tts_finished" }); }
        ttsPlaying = false;
        if (entered && !finishing) { setDot(paused ? "paused" : "listening"); }
        applyMuted();
      }
    });
    return speechChain;
  }
  function cutOffSpeech() {
    speechEpoch += 1;
    window.BlackoutSpeech.cancel();
  }
  async function requestWakeLock() {
    try { if (navigator.wakeLock && navigator.wakeLock.request) { wakeLock = await navigator.wakeLock.request("screen"); } } catch (e) {}
  }
  async function releaseWakeLock() {
    try { if (wakeLock && wakeLock.release) { await wakeLock.release(); } } catch (e) {}
    wakeLock = null;
  }
  async function requestFullscreen() {
    if (skipFullscreen) { return; }
    try {
      if (document.documentElement.requestFullscreen && !document.fullscreenElement) { await document.documentElement.requestFullscreen(); }
      if (document.fullscreenElement) { wasFullscreen = true; }
    } catch (e) {}
  }
  async function leaveFullscreen() {
    try { if (document.exitFullscreen && document.fullscreenElement) { await document.exitFullscreen(); } } catch (e) {}
  }
  function resetHint() {
    window.clearTimeout(hintTimer);
    window.clearTimeout(hintRemoveTimer);
    let hint = el("hint");
    if (!hint) {
      hint = document.createElement("div");
      hint.id = "hint";
      hint.className = "hint";
      hint.textContent = "空格暂停 · 说“结束”或按 Esc 结束";
      el("page-black").appendChild(hint);
    }
    hint.classList.remove("fading");
    hintTimer = window.setTimeout(function () {
      hint.classList.add("fading");
      hintRemoveTimer = window.setTimeout(function () { if (hint.parentNode) { hint.parentNode.removeChild(hint); } }, 1100);
    }, 5000);
  }
  function stopPolling() { window.clearInterval(pollTimer); pollTimer = 0; }
  async function stopCapture() {
    if (capture) { const current = capture; capture = null; await current.stop(); }
    if (recorder) {
      const currentRecorder = recorder;
      recorder = null;
      pttRecording = false;
      pttStarting = false;
      await currentRecorder.cancel();
    }
  }
  function closeSocket() {
    intentionalClose = true;
    window.clearTimeout(readyTimer);
    if (socket) { const current = socket; socket = null; try { current.close(); } catch (e) {} }
  }
  async function returnToStartForPermission() {
    flowGeneration += 1;
    await stopCapture();
    closeSocket();
    stopPolling();
    entered = false;
    await leaveFullscreen();
    await releaseWakeLock();
    showStart();
    window.BlackoutSpeech.speak("需要麦克风权限，请允许后重试。");
  }
  function isPermissionError(error) {
    return Boolean(error && (error.name === "NotAllowedError" || error.name === "SecurityError"));
  }
  async function startRealtimeCapture(gen) {
    capture = window.BlackoutCapture.createStreamCapture(function (frame) {
      try { if (socket && socket.readyState === WebSocket.OPEN && mode === "realtime") { socket.send(frame); } } catch (e) {}
    });
    applyMuted();
    try {
      const opened = await capture.start();
      if (!opened || gen !== flowGeneration || !entered) { await stopCapture(); return; }
